typedef struct Node {
    int value;
    struct Node* next;
} Node;

void makeCircular(Node* tail, Node* head) {
    tail->next = head; // intentional wraparound
}

void traverseOnce(Node* head) {
    Node* curr = head;
    do {
        printf("%d ", curr->value);
        curr = curr->next;
    } while (curr != head); // stop condition MUST check for head, not NULL
}

